        super().__init__(code)


def process_flow_request(payload, connect, call_factory):
    run_id = None

    def failure(code, stage, error_type=None):
        result = {
            "processing_status": "error",
            "error_code": code,
            "error_stage": stage,
            "run_id": run_id,
            "preliminary_status": None,
            "requires_teacher_review": True,
        }
        if error_type:
            result["error_type"] = error_type
        return result

    if not isinstance(payload, dict):
        return failure("invalid_input", "request_validation", "InvalidPayload")

    action = payload.get("action", "submit_and_review")
    if action not in {"submit", "review", "submit_and_review"}:
        return failure("invalid_input", "request_validation", "InvalidAction")

    expected = {"action", "telegram_id", "run_id"}
    if action != "review":
        expected.add("text")
    if set(payload) - expected or not {"telegram_id", "run_id"} <= set(payload):
        return failure("invalid_input", "request_validation", "InvalidFields")

    try:
        parsed = UUID(str(payload["run_id"]))
    except (ValueError, TypeError, AttributeError):
        return failure("invalid_input", "request_validation", "InvalidRunId")
    if parsed.version != 4:
        return failure("invalid_input", "request_validation", "InvalidRunId")
    run_id = str(parsed)

    telegram_id = payload["telegram_id"]
    if type(telegram_id) is not int or not 0 < telegram_id <= 9223372036854775807:
        return failure("invalid_input", "request_validation", "InvalidTelegramId")

    repo = FlowSubmissionRepository(connect)
    try:
        if action != "review":
            saved = repo.submit(
                telegram_id=telegram_id,
                text=payload.get("text"),
                run_id=run_id,
            )
            if action == "submit":
                return {"processing_status": "submitted", **saved}

        def evaluate(work):
            result = run_review(
                work,
                lambda request: review_one_block(request, call_factory, diagnostics=False),
            )
            if result["processing_status"] != "completed":
                raise ModelProcessingFailure(result.get("error_code", "model_failed"))
            return result

        saved = repo.review(
            telegram_id=telegram_id,
            run_id=run_id,
            call_reviewer=evaluate,
        )
        return {"processing_status": "completed", **saved}
    except ModelProcessingFailure as exc:
        logging.getLogger("reviewer.flow").exception(
            "Reviewer model failed run_id=%s", run_id
        )
        return failure(exc.code, "model", type(exc).__name__)
    except SubmissionNotFound as exc:
        return failure("student_or_submission_not_found", "authorization", type(exc).__name__)
    except FlowRunBusy as exc:
        return failure("run_busy", "repository", type(exc).__name__)
    except RunConflict as exc:
        return failure("run_conflict", "repository", type(exc).__name__)
    except ReviewError as exc:
        logging.getLogger("reviewer.flow").warning(
            "Reviewer validation failed run_id=%s error_type=%s detail=%s",
            run_id,
            type(exc).__name__,
            str(exc),
        )
        return failure("review_validation_failed", "repository_or_review", type(exc).__name__)
    except Exception as exc:
        logging.getLogger("reviewer.flow").exception(
            "Reviewer execution failed run_id=%s", run_id
        )
        return failure("database_or_processing_failed", "execution", type(exc).__name__)
