_flow_modules = {}
_real_import = builtins.__import__
def _local_import(name, globals=None, locals=None, fromlist=(), level=0):
    if level == 0 and name in _flow_modules:
        return _flow_modules[name]
    return _real_import(name, globals, locals, fromlist, level)

def _load_flow_modules():
    global _flow_modules
    if _flow_modules:
        return _flow_modules
    for _name, _source in _flow_sources.items():
        _module = types.ModuleType(_name)
        _module.__dict__['__builtins__'] = {**vars(builtins), '__import__':_local_import}
        _flow_modules[_name] = _module
        exec(compile(_source, '<reviewer-flow:' + _name + '>', 'exec'), _module.__dict__)
    return _flow_modules

from langflow.custom import Component
from langflow.io import MessageTextInput, Output
from lfx.inputs.inputs import DropdownInput
from openai import OpenAI
from langflow.schema.message import Message

def make_timeweb_client(client, model, result_schema):
    modules = _load_flow_modules()
    ReviewError = modules["flow_model_rules"].ReviewError
    ReviewerCoreError = modules["reviewer_core"].ReviewError
    if not isinstance(model, str) or not model.strip():
        raise ReviewError("invalid_model_name")

    def call(system, user):
        try:
            response = client.chat.completions.create(
                model=model,
                messages=[
                    {"role": "system", "content": system},
                    {"role": "user", "content": user},
                ],
                temperature=0.1,
                max_tokens=10000,
                response_format={
                    "type": "json_schema",
                    "json_schema": {
                        "name": "review_result",
                        "strict": True,
                        "schema": result_schema,
                    },
                },
            )
            if not response.choices:
                raise ReviewError("invalid_model_response")
            choice = response.choices[0]
            if choice.finish_reason == "length":
                raise ReviewError("incomplete_model_response")
            content = choice.message.content
            if not isinstance(content, str) or not content.strip():
                raise ReviewError("invalid_model_response")
            try:
                return modules["reviewer_core"].strict_json(content)
            except ReviewerCoreError as exc:
                raise ReviewError(getattr(exc, "code", "invalid_model_response")) from exc
        except ReviewError:
            raise
        except Exception as exc:
            raise ReviewError("model_unavailable") from exc

    return call


