                )
            client = OpenAI(
                api_key=os.environ['TIMEWEB_AI_API_KEY'],
                base_url=os.getenv('TIMEWEB_AI_BASE_URL', 'https://api.timeweb.ai/v1'),
                timeout=75,
                max_retries=0,
